module CountValidStrings(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [5:0] rule_in_idx,\n    input wire [11:0] rule_in_2char,\n    input wire [5:0] rule_in_dest,\n    input wire rule_write,\n    input wire [2:0] n,\n    output reg [23:0] result,\n    output reg done,\n    output reg busy\n);\n\n    // State definitions\n    localparam [1:0] IDLE      = 2'd0;\n    localparam [1:0] PROGRAM   = 2'd1;\n    localparam [1:0] COMPUTE   = 2'd2;\n    localparam [1:0] FINISH    = 2'd3;\n\n    // Rule table: 36 entries\n    // Each entry: {valid, first, second, dest}\n    reg [22:0] rule_table [0:35];  // 1 + 6 + 6 + 6 = 23 bits\n    reg [5:0] rule_idx;\n    reg [22:0] rule_data;\n\n    // Current and next count arrays (size 6)\n    reg [23:0] current [0:5];\n    reg [23:0] next [0:5];\n    reg [23:0] sum_temp;\n\n    // Loop counters and state\n    reg [2:0] current_len;\n    reg [5:0] letter_idx;\n    reg [5:0] rule_iter;\n    reg [1:0] compute_state;\n    localparam [1:0] COMP_INIT     = 2'd0;\n    localparam [1:0] COMP_OUTER    = 2'd1;\n    localparam [1:0] COMP_INNER    = 2'd2;\n    localparam [1:0] COMP_SUM      = 2'd3;\n\n    // Main state\n    reg [1:0] state;\n    reg [2:0] n_reg;\n    reg start_d;\n    integer i, j;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Reset state\n            state <= IDLE;\n            busy <= 1'b0;\n            done <= 1'b0;\n            result <= 24'd0;\n            n_reg <= 3'd0;\n            start_d <= 1'b0;\n            compute_state <= COMP_INIT;\n            current_len <= 3'd0;\n            letter_idx <= 6'd0;\n            rule_iter <= 6'd0;\n            sum_temp <= 24'd0;\n            // Clear rule table\n            for (i = 0; i < 36; i = i + 1) begin\n                rule_table[i] <= 23'd0;\n            end\n            // Clear count arrays\n            for (j = 0; j < 6; j = j + 1) begin\n                current[j] <= 24'd0;\n                next[j] <= 24'd0;\n            end\n        end else begin\n            start_d <= start;\n            // Default assignments\n            done <= 1'b0;\n            rule_data <= rule_table[rule_in_idx];\n\n            case (state)\n                IDLE: begin\n                    busy <= 1'b0;\n                    if (start && !start_d) begin\n                        // Start computation\n                        state <= COMPUTE;\n                        busy <= 1'b1;\n                        compute_state <= COMP_INIT;\n                        n_reg <= n;\n                        current_len <= 3'd0;\n                        letter_idx <= 6'd0;\n                        rule_iter <= 6'd0;\n                        sum_temp <= 24'd0;\n                    end else if (rule_write) begin\n                        // Program rule\n                        state <= PROGRAM;\n                        busy <= 1'b1;\n                    end\n                end\n\n                PROGRAM: begin\n                    if (rule_write) begin\n                        // Store rule\n                        rule_table[rule_in_idx] <= {1'b1, rule_in_2char[11:6], rule_in_2char[5:0], rule_in_dest};\n                    end\n                    // Return to idle if no more writes or start is pressed\n                    if (!rule_write) begin\n                        state <= IDLE;\n                        busy <= 1'b0;\n                    end\n                end\n\n                COMPUTE: begin\n                    // Initialize arrays\n                    if (compute_state == COMP_INIT) begin\n                        // Clear next array\n                        for (j = 0; j < 6; j = j + 1) begin\n                            next[j] <= 24'd0;\n                        end\n                        // Initialize current: all zeros except current['a']=1\n                        for (j = 0; j < 6; j = j + 1) begin\n                            current[j] <= (j == 6'd0) ? 24'd1 : 24'd0;\n                        end\n                        current_len <= 3'd1;\n                        compute_state <= COMP_OUTER;\n                    end\n                    // Outer loop: iterate until current_len == n_reg\n                    else if (compute_state == COMP_OUTER) begin\n                        if (current_len < n_reg) begin\n                            // Start new iteration\n                            letter_idx <= 6'd0;\n                            // Clear next array for this iteration\n                            for (j = 0; j < 6; j = j + 1) begin\n                                next[j] <= 24'd0;\n                            end\n                            compute_state <= COMP_INNER;\n                        end else begin\n                            // Done, compute sum\n                            compute_state <= COMP_SUM;\n                        end\n                    end\n                    // Inner loop: iterate over letters and rules\n                    else if (compute_state == COMP_INNER) begin\n                        // Check if letter_idx done (6 letters)\n                        if (letter_idx < 6'd6) begin\n                            // Check if rule_iter done (36 rules)\n                            if (rule_iter < 6'd36) begin\n                                // Check if rule matches\n                                if (rule_table[rule_iter][22]) begin\n                                    // Rule is valid\n                                    if (rule_table[rule_iter][5:0] == letter_idx) begin\n                                        // Destination matches current letter_idx\n                                        // Get first letter (k) and add current[j] to next[k]\n                                        // First letter is bits [20:15] of rule entry\n                                        if (next[rule_table[rule_iter][20:15]] + current[letter_idx] < 24'hFFFFFF) begin\n                                            next[rule_table[rule_iter][20:15]] <= next[rule_table[rule_iter][20:15]] + current[letter_idx];\n                                        end else begin\n                                            next[rule_table[rule_iter][20:15]] <= 24'hFFFFFF;\n                                        end\n                                    end\n                                end\n                                rule_iter <= rule_iter + 6'd1;\n                            end else begin\n                                // Done with rules for this letter\n                                rule_iter <= 6'd0;\n                                letter_idx <= letter_idx + 6'd1;\n                            end\n                        end else begin\n                            // Done with all letters\n                            // Copy next to current\n                            for (j = 0; j < 6; j = j + 1) begin\n                                current[j] <= next[j];\n                            end\n                            current_len <= current_len + 3'd1;\n                            compute_state <= COMP_OUTER;\n                        end\n                    end\n                    // Sum phase\n                    else if (compute_state == COMP_SUM) begin\n                        // Sum all current[j]\n                        sum_temp <= current[0] + current[1] + current[2] + current[3] + current[4] + current[5];\n                        state <= FINISH;\n                        busy <= 1'b1;\n                    end\n                end\n\n                FINISH: begin\n                    result <= sum_temp;\n                    done <= 1'b1;\n                    state <= IDLE;\n                    busy <= 1'b0;\n                end\n\n                default: begin\n                    state <= IDLE;\n                    busy <= 1'b0;\n                    done <= 1'b0;\n                end\n            endcase\n        end\n    end\n\nendmodule